function UIPolePlotEndRewardPopupDialog:InitData()
    self._allReardId = QuestConfMgr:GetInstance():GetRoleStoryRewardIdsByChapterId(self._curChapterId)

    for i = 1, #self._allReardId - 1 do
        for j = i + 1, #self._allReardId do
            local id1 = self._allReardId[i]
            local id2 = self._allReardId[j]

            local isTrue = false
            local isDraw1 = QuestConfMgr:GetInstance():IsDrawRoleQuestRewardById(id1)
            local isDraw2 = QuestConfMgr:GetInstance():IsDrawRoleQuestRewardById(id2)

            if (isDraw1 and isDraw2) or ((not isDraw1) and (not isDraw2)) then
                isTrue = checkNumber(id2) < checkNumber(id1)
            elseif (isDraw1 and (not isDraw2)) then
                isTrue = true
            else
                local isCanDraw1 = QuestConfMgr:GetInstance():IsCanDrawRoleQuestRewardById(id1)
                local isCanDraw2 = QuestConfMgr:GetInstance():IsCanDrawRoleQuestRewardById(id2)
                if (isCanDraw1 and isCanDraw2) or ((not isCanDraw1) and (not isCanDraw2)) then
                    isTrue = checkNumber(id2) < checkNumber(id1)
                else
                    if isCanDraw2 then
                        isTrue = true
                    end
                end
            end
            if isTrue then
                local data = self._allReardId[i]
                self._allReardId[i] = self._allReardId[j]
                self._allReardId[j] = data
            end
        end
    end
end

function UIPolePlotEndRewardPopupDialog:FillSelf()
    if self._isInitList then
        GameUtils.ReloadData(self.ListContent, table.count(self._allReardId))
    else
        self.ListContent:InitListView(table.count(self._allReardId), Bind(self, self.OnGetCellIndex))
        self._isInitList = true
    end
end

function UIPolePlotEndRewardPopupDialog:OnGetCellIndex(listView, index)
    if index < 0 then
        return nil
    end

    local cell = listView:NewListViewItem("Cell")
    local id = self._allReardId[index + 1]
    local scr = CfUtils.GetLuaScr(cell, UIPolePlotEndRewardPopupRewardNode)
    if scr then
        scr:Refresh(id, function()
            self:FillSelf()
        end)
        scr:PlayAni("Go")
    end

    return cell    
end

